      "alertLine1": {
        "type": "string",
        "description": "环形进度中心的第一行告警文案。",
        "sampleValue": "今日已超限"
      },
      "alertLine2": {
        "type": "string",
        "description": "环形进度中心的第二行告警时长。",
        "sampleValue": "45分钟"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/moon_circle_fill.svg",
      "description": "月亮圆形实心图标，黑白双色，适合夜间、睡眠和专注提醒场景的左侧主视觉。"
    }
  ]
}

